INSERT INTO settings (key, value) VALUES ('about', '{"bio":["I’m a Data Analytics and Computer Information Systems student at Bentley University who loves building software that turns data into something people can use.","Most recently I built an AI-powered ERP test data generator at Gemline, and I’m co-founding Move, a ridesharing platform for students. When I’m not coding, I’m teaching bass guitar and music theory."],"playgroundLabel":"Drag things around","playgroundWords":["code","data","bass"],"interests":[{"text":"Skiing","color":"#6cb4ff","top":8,"left":6,"rotate":-8},{"text":"Wakeboarding","color":"#5ee0f0","top":14,"left":48,"rotate":10},{"text":"Climbing","color":"#b5e35d","top":30,"left":20,"rotate":4},{"text":"Bass","color":"#ff6a1f","top":46,"left":62,"rotate":-14},{"text":"Soccer","color":"#f2c46d","top":52,"left":8,"rotate":12},{"text":"Cars","color":"#c79bff","top":66,"left":38,"rotate":-5},{"text":"Ecuador","color":"#7aa2ff","top":80,"left":4,"rotate":6},{"text":"Boston","color":"#34f33e","top":82,"left":62,"rotate":-9}],"currentlyBuilding":{"slug":"move","blurb":"A ridesharing app for students, which I’m co-founding. See the project →"},"techStack":{"title":"Tech stack","text":"The languages and tools I reach for most, from data work in Python and SQL to web apps in React.","innerRing":[{"name":"python","src":"/logos/python.svg"},{"name":"typescript","src":"/logos/typescript.svg"},{"name":"react","src":"/logos/react.svg"},{"name":"java","src":"/logos/java.svg"},{"name":"postgresql","src":"/logos/postgresql.svg"}],"outerRing":[{"name":"javascript","src":"/logos/javascript.svg"},{"name":"fastapi","src":"/logos/fastapi.svg"},{"name":"supabase","src":"/logos/supabase.svg"},{"name":"git","src":"/logos/git.svg"},{"name":"tailwindcss","src":"/logos/tailwindcss.svg"},{"name":"jupyter","src":"/logos/jupyter.svg"}]}}') ON CONFLICT (key) DO UPDATE SET value = excluded.value;
