INSERT INTO projects (slug, title, tagline, description, highlights, image, image_alt, tools, github_url, live_url, date, status, featured, sort_order) VALUES ('move', 'Move', 'Student ridesharing that connects verified student drivers with student commuters.', 'A full-stack web and mobile ridesharing platform I am co-founding. Students sign up with their university (.edu) email, which creates trust-based, community-driven access to shared rides.', '["Architecting the full system: ride posting and discovery with location and time filtering","In-app messaging plus a rating and review system for both drivers and riders","Leading frontend (React Native / React.js) and backend (FastAPI + Supabase) development"]', '/projects/move.svg', 'Move — coming soon', '["React Native","React.js","TypeScript","FastAPI","Supabase","Cloudflare"]', '', '', 'Aug 2026 – Present', 'in-development', 1, 0);
INSERT INTO projects (slug, title, tagline, description, highlights, image, image_alt, tools, github_url, live_url, date, status, featured, sort_order) VALUES ('order-test-data-generator', 'ERP Test Data Generator', 'AI-powered test data integrated into an ERP: from 12 orders an hour to 1,000+ in minutes.', 'A four-stage pipeline that turns a plain-English request into realistic orders.
INSERT INTO projects (slug, title, tagline, description, highlights, image, image_alt, tools, github_url, live_url, date, status, featured, sort_order) VALUES ('boston-trees', 'Boston Trees', 'Interactive map of the trees planted across Boston, with user-controlled filters.', 'A data visualization app that maps trees planted across Boston. Users control the filters and the map to explore the data. Frontend and backend are built entirely in Python with Streamlit.', '["Interactive mapping with user-controlled filtering","Managed both frontend and backend entirely in Python"]', '/projects/boston-trees.webp', 'Screenshot of the Boston Trees dashboard showing a bar chart of trees per neighborhood', '["Python","Streamlit","Pandas"]', 'https://github.com/maurice523/boston-trees-app', 'https://trees.mauriceneme.com', 'Jan 2026', 'completed', 0, 2);
INSERT INTO projects (slug, title, tagline, description, highlights, image, image_alt, tools, github_url, live_url, date, status, featured, sort_order) VALUES ('excel-io', 'Excel-io', 'A spreadsheet built from scratch in Java, with its own formula language. Playable in your browser.', 'A desktop spreadsheet written in Java: a grid you type into, a formula bar, and formulas that reference other cells and ranges. The formula language is hand-written — a lexer turns the text into tokens, a parser builds a tree that respects operator precedence, and an evaluator walks it. The browser demo runs the real app with CheerpJ.', '["Hand-written lexer, parser and evaluator — no spreadsheet libraries","12 functions including SUM, AVG, IF, ROUND and CONCAT","Changing a cell recalculates everything that depends on it","Swing interface with a formula bar, plus save and open"]', '/projects/excel-io.webp', 'Screenshot of the Excel-io spreadsheet grid running in the browser', '["Java","Swing","JUnit","Gradle"]', 'https://github.com/maurice523/excel-io', 'https://excelio.mauriceneme.com', 'Nov 2025', 'completed', 0, 3);
INSERT INTO projects (slug, title, tagline, description, highlights, image, image_alt, tools, github_url, live_url, date, status, featured, sort_order) VALUES ('portfolio', 'This Portfolio', 'The site you’re on! A portfolio built to grow, designed for web and mobile.', 'My personal portfolio for introductions and project display. Everything on it — projects, text and color themes — is edited from an admin dashboard and stored in Cloudflare D1, so updates go live without a redeploy. It is responsive from phone to desktop and runs on Cloudflare Workers.', '["Content, projects and color themes edited from a protected /admin dashboard","Cloudflare Workers + D1 + R2, with Cloudflare Access guarding the admin","Mobile-first responsive design with Tailwind CSS"]', '/projects/portfolio.webp', 'Screenshot of this portfolio’s hero section with the 3D bass guitar', '["React","TypeScript","Tailwind CSS","Vite","Cloudflare"]', 'https://github.com/maurice523/portfolio', 'https://mauriceneme.com', 'Jul 2026 – Present', 'in-development', 0, 4);
INSERT INTO experience (company, role, date, bullets, sort_order) VALUES ('Gemline', 'Software Development Intern', 'Jun 2026 – Aug 2026', '["Built an AI-powered ERP test data generator using Python, BAML, the OpenAI API and React.js","Integrated into company production ERP system","Implemented a data pipeline that generated output based on statistical analysis","Cut order entry from 12 orders per hour to 1,000+ orders in minutes","Presented the product to Gemline’s Executive Leadership Team and Board Chair"]', 0);
INSERT INTO experience (company, role, date, bullets, sort_order) VALUES ('Deloitte', 'Audit & Assurance Intern (Human Capital Analytics)', 'Jul 2024 – Aug 2024', '["Cleaned and analyzed historical employee turnover data to identify drivers of attrition","Modeled incentive structures, projecting an estimated 11% improvement in retention","Produced client-ready visualizations and reports under Deloitte’s analytics standards"]', 1);
INSERT INTO experience (company, role, date, bullets, sort_order) VALUES ('Self-employed', 'Private Music Tutor', 'Jul 2023 – Present', '["Taught 29+ beginner and intermediate students bass guitar and music theory","Grew my client base mostly through word-of-mouth referrals and reviews"]', 2);
